using LocalCRM.Models; using Microsoft.EntityFrameworkCore; namespace LocalCRM.Data; public sealed class CrmDbContext(DbContextOptions<CrmDbContext> options):DbContext(options){public DbSet<Contact> Contacts=>Set<Contact>(); protected override void OnModelCreating(ModelBuilder b){b.Entity<Contact>().Property(x=>x.Name).HasMaxLength(80).IsRequired();b.Entity<Contact>().Property(x=>x.Email).HasMaxLength(160).IsRequired();b.Entity<Contact>().Property(x=>x.Stage).HasMaxLength(20).IsRequired();}}
